/// <summary>
/// Make number sequence company scope configurationable
/// </summary>
[ExtensionOf(classStr(NumberSeqDataType))]
final class AVANumberSeqDataType_cls_Extension
{
}

Method.Source:
 /// <summary>
 ///    Adds a new parameter type for the data type.
 /// </summary>
 /// <param name="_type">
 ///    The enumeration value that indicates the parameter type to be added to the scope type of the data
 ///    type.
 /// </param>
 /// <param name="_isEnabled">
 ///    A Boolean value that indicates whether the parameter type is enabled.
 /// </param>
 /// <param name="_isConfigurable">
 ///    A Boolean value that indicates whether the parameter type is configurable.
 /// </param>
 /// <returns>
 ///    true if the parameter type was added; otherwise, false.
 /// </returns>
 public boolean addParameterType(NumberSeqParameterType  _type,
                                 boolean                 _isEnabled,
                                 boolean                 _isConfigurable )
{
     boolean retVal;
     boolean isConfigurableLocal = _isConfigurable;

     if (this.parmDataTypeId() == extendedTypeNum(KCS_KBVBuildingProjectID))
     {
         isConfigurableLocal = true;
     }
     retVal = next addParameterType(_type, _isEnabled, isConfigurableLocal);

     return retVal;
 }
